 static void check(boolean v,String m){if(!v)throw new AssertionError(m);} static byte[] b(String s){return s.getBytes(java.nio.charset.StandardCharsets.UTF_8);} static String hash(byte[] b)throws Exception{return Payload.hex(MessageDigest.getInstance("SHA-256").digest(b));}
