  Path dir=Files.createTempDirectory("airsoft491-test-");Path update=Files.createDirectory(dir.resolve("update")),sentinel=dir.resolve("unrelated-video.mp4");Files.write(sentinel,b("preserve"));Path stale=dir.resolve(".airsoft-install-12345678-1234-1234-1234-123456789abc.part");Files.write(stale,b("partial"));
