   try(java.net.Socket client=new java.net.Socket(java.net.InetAddress.getLoopbackAddress(),server.getLocalPort())){client.setSoTimeout(5000);DataInputStream input=new DataInputStream(client.getInputStream());DataOutputStream output=new DataOutputStream(client.getOutputStream());check(input.readUTF().equals("NEED:"+e.name),"transfer request");output.writeLong(e.size);output.flush();check(input.readUTF().startsWith("Installing downloaded file:"),"receiver readiness");output.write(b("changed-"+e.name));output.writeUTF(e.sha256);output.flush();check(input.readUTF().startsWith("Installed and verified:"),"verified completion");}worker.get(5,java.util.concurrent.TimeUnit.SECONDS);
