  Files.write(target,b("original-"+e.name));Files.createDirectory(update);Files.write(update.resolve("keep"),b("important"));try{Airsoft491.preflight(dir.toFile(),payload,new DataOutputStream(new ByteArrayOutputStream()));throw new AssertionError("nonempty folder accepted");}catch(IOException expected){}check(Files.exists(update.resolve("keep")),"nested data changed");System.out.println("PASS Airsoft manifest/routing, safe preflight, verified transfer, corrupt data, unrelated files, and folder handling");
